/// <summary>
/// 通用检测区域脚本，挂载在带有Collider2D(isTrigger)的子对象上
/// 检测带有指定Tag的目标是否进入区域，并记录最后已知位置
/// </summary>
public class DetectionZone : MonoBehaviour
{
    [Tooltip("要检测的目标Tag（目视/攻击启动/转身检测器用\"Player\"，受击框用\"PlayerHitbox\"）")]
    public string targetTag = "Player";

    /// <summary>目标是否在区域内</summary>
    public bool TargetInZone { get; private set; }

    /// <summary>区域内的目标碰撞体</summary>
    public Collider2D TargetCollider { get; private set; }

    /// <summary>目标最后已知位置</summary>
    public Vector2 LastKnownPosition { get; private set; }

    /// <summary>目标进入区域时触发</summary>
    public event Action<Collider2D> OnTargetEnter;

    /// <summary>目标离开区域时触发</summary>
    public event Action<Collider2D> OnTargetExit;

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag(targetTag))
        {
            TargetInZone = true;
            TargetCollider = other;
            LastKnownPosition = other.transform.position;
            OnTargetEnter?.Invoke(other);
        }
    }

    private void OnTriggerStay2D(Collider2D other)
    {
        if (other.CompareTag(targetTag))
        {
            LastKnownPosition = other.transform.position;
        }
    }

    private void OnTriggerExit2D(Collider2D other)
    {
        if (other.CompareTag(targetTag))
        {
            TargetInZone = false;
            TargetCollider = null;
            OnTargetExit?.Invoke(other);
        }
    }
}

using UnityEngine;
using System;

/// <summary>
/// 攻击判定框组件
/// 挂载在攻击检测子对象上（需有 Collider2D isTrigger + DetectionZone）
/// 默认禁用游戏对象，启用后只造成一次伤害自动禁用
///
/// Tag 规则（挂载在哪个对象上就设哪个Tag）：
///   玩家攻击框 → Tag: PlayerAttackBox    → 自动检测 EnemyHurtBox
///   敌人攻击框 → Tag: EnemyAttackBox     → 自动检测 PlayerHurtBox
/// </summary>
[RequireComponent(typeof(DetectionZone))]
public class AttackHitbox : MonoBehaviour
{
    private DetectionZone _detectionZone;
    private bool _hasHit;

    /// <summary>命中目标时触发，参数为目标碰撞体</summary>
    public event Action<Collider2D> OnHit;

    private void Awake()
    {
        _detectionZone = GetComponent<DetectionZone>();
        AutoSetTargetTag();
    }

    /// <summary>
    /// 根据自身 Tag 自动设置要检测的目标 Tag
    /// </summary>
    private void AutoSetTargetTag()
    {
        switch (gameObject.tag)
        {
            case "PlayerAttackBox":
                _detectionZone.targetTag = "EnemyHurtBox";
                break;
            case "EnemyAttackBox":
                _detectionZone.targetTag = "PlayerHurtBox";
                break;
        }
    }

    private void OnEnable()
    {
        _hasHit = false;
        _detectionZone.OnTargetEnter += HandleTargetEnter;
    }

    private void OnDisable()
    {
        _detectionZone.OnTargetEnter -= HandleTargetEnter;
    }

    private void HandleTargetEnter(Collider2D target)
    {
        if (_hasHit) return;
        _hasHit = true;
        OnHit?.Invoke(target);
        gameObject.SetActive(false);
    }

    /// <summary>
    /// 兜底：攻击框启用时若已与目标重叠，OnTriggerEnter2D 不会再触发
    /// </summary>
    private void OnTriggerStay2D(Collider2D other)
    {
        if (_hasHit) return;
        if (!other.CompareTag(_detectionZone.targetTag)) return;
        HandleTargetEnter(other);
    }

    /// <summary>启用攻击框（新一击）</summary>
    public void Activate()
    {
        gameObject.SetActive(true);
    }

    /// <summary>禁用攻击框</summary>
    public void Deactivate()
    {
        gameObject.SetActive(false);
    }
}

